char *decrypt (const char *s) {
    int crypt [4096];
    int ncrypt = 0;
    size_t slen = strlen (s);
    int ngroups = 1;
    for (size_t q = 0; q < slen; q++) {
        if (s [q] == '#') ngroups++;
    }
    const char *p = s;
    for (int gi = 0; gi < ngroups; gi++) {
        char group [256];
        int glen = 0;
        while (*p && *p != '#') {
            group [glen++] = *p++;
        }
        if (*p == '#') p++;
        group [glen] = '\0';
        int j = 0;
        if (gi == ngroups - 1 && (slen == 0 || s [slen - 1] != '#')) {
            j = glen;
        }
        if (glen > 2) {
            j = glen - 2;
        }
        for (int k = 0; k < j; k++) {
            crypt [ncrypt++] = group [k] - '0';
        }
        if (j < glen) {
            crypt [ncrypt++] = atoi (group + j);
        }
    }
    char *n = malloc ((size_t) ncrypt + 1);
    for (int i = 0; i < ncrypt; i++) {
        n [i] = (char) ((('a' + crypt [i]) - 1));
    }
    n [ncrypt] = '\0';
    return n;
