            j = group.Length - 2;
        }
        for (int k = 0; k < j; k++) {
            crypt.Add (int.Parse (group.Substring (k, 1)));
        }
        if (j < group.Length) {
            crypt.Add (int.Parse (group.Substring (j, group.Length - j)));
        }
    }
    var n = new StringBuilder (crypt.Count);
