public static string Format (this TimeSpan obj) {
    var parts = new (int value, string name) [] {
        (obj.Hours, "hours"),
        (obj.Minutes, "minutes"),
        (obj.Seconds, "seconds"),
        (obj.Milliseconds, "Milliseconds")
    };
    StringBuilder sb = new StringBuilder ();
    foreach (var part in parts) {
        if (part.value != 0 || sb.Length != 0) {
            sb.Append (part.value).Append (" ").Append (part.name).Append (" ");
        }
    }
    if (sb.Length == 0) {
        sb.Append (0).Append (" ").Append ("Milliseconds");
    }
    return sb.ToString ();
}

